<script lang="ts">
 import { onMount } from 'svelte';
 import { DEFAULT_WEEKLY_BOOKING_HOURS, bookingDayHours } from '../../lib/booking';
 type Locale='en'|'th';
 type SlotStatus='available'|'contact_directly'|'booked'|'unavailable';
 type Hours=Record<string,'available'|'contact_directly'>;
 type CalendarSlot={startAt:string;endAt:string;status:SlotStatus};
 type BookingDetail={id:string;startAt:string;endAt:string;status:string;instrument:string;service:string;notes:string;contactName:string;contactInformation:string};
 type Payload={timeZone:'Asia/Bangkok';source:'google-calendar'|'database'|'unavailable';availabilityError:string|null;weeklyHours:Record<string,Hours>;overrides:Record<string,Hours>;calendarSlots:CalendarSlot[];bookings:BookingDetail[];from:string;to:string};
 let {lang}=$props<{lang:Locale}>();
 const words={
  en:{title:'Repair booking calendar',lead:'Set availability for a specific date. Bookings last one hour and start every 30 minutes; keep the following half-hour open too.',loading:'Loading calendar…',loadError:'The calendar could not be loaded.',setupRequired:'Calendar database setup is incomplete. Apply the Supabase booking calendar migrations, then refresh.',retry:'Refresh calendar',refresh:'Refresh availability',refreshing:'Refreshing…',sourceGoogle:'Google Calendar synced',sourceDb:'Website schedule only',zone:'Times shown in Asia/Bangkok',window:'Bookable dates',prev:'Previous month',next:'Next month',date:'Selected date',default:'Using weekly default',override:'Date-specific schedule',reset:'Reset to weekly default',save:'Save this date',saving:'Saving…',open:'Available',contact:'Contact directly',closed:'Closed',booked:'Booked',busy:'Busy calendar time',slotUnavailable:'Unavailable',weekend:'Closed by weekly default',unsaved:'Unsaved changes are preserved while availability refreshes.',saved:'Date schedule saved.',resetDone:'Date reset to weekly default.',saveError:'Could not save this date. Your changes are still here; try again.',resetError:'Could not reset this date. Your changes are still here; try again.',status:'Calendar status',slots:'30-minute schedule',note:'A one-hour appointment needs this start time and the following half-hour to be open.',emptyDay:'No schedule set for this date. It is closed.',from:'From',to:'To',noWindow:'Outside the booking window',overrideExists:'Custom schedule',sourceUnavailable:'Unavailable',syncFailed:'Google Calendar could not be checked. The schedule and day edits are available; customer bookings are paused until sync is restored.',refreshFailed:'Refresh failed. The last calendar data is still shown.'},
  th:{title:'ปฏิทินนัดหมายงานซ่อม',lead:'กำหนดเวลาว่างสำหรับวันที่เลือก การนัดหมายใช้เวลา 1 ชั่วโมงและเริ่มทุก 30 นาที โดยต้องเปิดช่วงครึ่งชั่วโมงถัดไปด้วย',loading:'กำลังโหลดปฏิทิน…',loadError:'โหลดปฏิทินไม่สำเร็จ',setupRequired:'การตั้งค่าฐานข้อมูลปฏิทินยังไม่ครบ โปรดติดตั้ง Supabase booking calendar migrations แล้วโหลดใหม่',retry:'โหลดปฏิทินอีกครั้ง',refresh:'รีเฟรชเวลาว่าง',refreshing:'กำลังรีเฟรช…',sourceGoogle:'ซิงก์กับ Google Calendar แล้ว',sourceDb:'แสดงเฉพาะตารางเวลาบนเว็บไซต์',zone:'เวลาแสดงตาม Asia/Bangkok',window:'วันที่เปิดให้จอง',prev:'เดือนก่อน',next:'เดือนถัดไป',date:'วันที่เลือก',default:'ใช้เวลาเปิดประจำสัปดาห์',override:'กำหนดเวลาเฉพาะวันนี้',reset:'กลับไปใช้เวลาเปิดประจำสัปดาห์',save:'บันทึกวันนี้',saving:'กำลังบันทึก…',open:'ว่าง',contact:'ติดต่อร้านโดยตรง',closed:'ปิด',booked:'มีการจองแล้ว',busy:'มีนัดในปฏิทิน',slotUnavailable:'ไม่ว่าง',weekend:'ปิดตามตารางประจำสัปดาห์',unsaved:'การรีเฟรชจะเก็บการแก้ไขที่ยังไม่บันทึกไว้',saved:'บันทึกตารางของวันนี้แล้ว',resetDone:'กลับไปใช้เวลาเปิดประจำสัปดาห์แล้ว',saveError:'บันทึกวันนี้ไม่สำเร็จ การแก้ไขยังอยู่ โปรดลองอีกครั้ง',resetError:'รีเซ็ตวันนี้ไม่สำเร็จ การแก้ไขยังอยู่ โปรดลองอีกครั้ง',status:'สถานะปฏิทิน',slots:'ตารางช่วงละ 30 นาที',note:'การนัดหมาย 1 ชั่วโมงต้องเปิดช่วงเริ่มต้นและช่วงครึ่งชั่วโมงถัดไป',emptyDay:'ยังไม่ได้กำหนดเวลา วันนี้จึงปิด',from:'เริ่ม',to:'ถึง',noWindow:'อยู่นอกช่วงวันที่เปิดจอง',overrideExists:'กำหนดเวลาเฉพาะวัน',sourceUnavailable:'ไม่ว่าง',syncFailed:'ตรวจสอบ Google Calendar ไม่สำเร็จ ยังดูและแก้ไขตารางรายวันได้ แต่ระบบหยุดรับการจองจนกว่าจะซิงก์ได้อีกครั้ง',refreshFailed:'รีเฟรชไม่สำเร็จ กำลังแสดงข้อมูลปฏิทินล่าสุดที่โหลดได้'}};
 const t=(key:keyof typeof words.en)=>words[lang][key];
 let data=$state<Payload|null>(null),loadError=$state(false),setupRequired=$state(false),refreshing=$state(false),busy=$state(false),message=$state('');
 let selectedDate=$state(''),viewMonth=$state(''),drafts=$state<Record<string,Hours>>({}),dirtyDates=$state<Record<string,boolean>>({});
 let weeklyDraft=$state<Record<string,Hours>>({}),weeklyDirty=$state(false),weeklyMessage=$state('');
 const weeklyWords={en:{title:'Weekly default hours',description:'Opening hours repeat automatically. Save the default, apply it to this week, then adjust individual dates below. Existing date exceptions are kept.',day:'Day',open:'Open',from:'From',to:'Until',save:'Save weekly default',apply:'Apply default to selected week',restore:'Set Monday–Friday 08:00–18:00',saved:'Weekly default saved.',applied:'Default applied. Existing date exceptions and bookings were kept.',error:'Could not save. Your edits are kept; try again.',rangeError:'Closing time must be after opening time.',unsaved:'Save weekly changes before applying them.'},th:{title:'เวลาเปิดประจำสัปดาห์',description:'เวลาเปิดจะใช้ซ้ำโดยอัตโนมัติ บันทึกค่าเริ่มต้นแล้วนำไปใช้กับสัปดาห์ที่เลือก จากนั้นแก้ไขเฉพาะวันด้านล่าง โดยคงข้อยกเว้นรายวันไว้',day:'วัน',open:'เปิด',from:'ตั้งแต่',to:'ถึง',save:'บันทึกเวลาเปิดประจำสัปดาห์',apply:'ใช้ค่าเริ่มต้นกับสัปดาห์ที่เลือก',restore:'ตั้งจันทร์–ศุกร์ 08:00–18:00',saved:'บันทึกเวลาเปิดประจำสัปดาห์แล้ว',applied:'นำค่าเริ่มต้นไปใช้แล้ว โดยคงข้อยกเว้นรายวันและการจองเดิมไว้',error:'บันทึกไม่สำเร็จ การแก้ไขยังอยู่ โปรดลองอีกครั้ง',rangeError:'เวลาปิดต้องอยู่หลังเวลาเปิด',unsaved:'โปรดบันทึกเวลาเปิดก่อนนำไปใช้'}};
 const w=(key:keyof typeof weeklyWords.en)=>weeklyWords[lang][key];
 const weekDays=[1,2,3,4,5,6,0];
 const weekDayLabel=(day:number)=>new Intl.DateTimeFormat(lang,{weekday:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2026,9,18+day)));
 function hoursRange(day:number){const times=Object.keys(weeklyDraft[String(day)]??{}).sort();if(!times.length)return {start:'08:00',end:'18:00'};const last=times.at(-1)!,end=Number(last.slice(0,2))*60+Number(last.slice(3))+30;return {start:times[0],end:`${String(Math.floor(end/60)).padStart(2,'0')}:${String(end%60).padStart(2,'0')}`};}
 function changeWeekDay(day:number,enabled:boolean,start=hoursRange(day).start,end=hoursRange(day).end){if(enabled&&start>=end){weeklyMessage='rangeError';return;}const hours:Hours=enabled?bookingDayHours(start,end):{};weeklyDraft={...weeklyDraft,[String(day)]:hours};weeklyDirty=true;weeklyMessage='';}
 function restoreWeek(){weeklyDraft=Object.fromEntries(Array.from({length:7},(_,day)=>[String(day),{...DEFAULT_WEEKLY_BOOKING_HOURS[String(day)]}]));weeklyDirty=true;weeklyMessage='';}
 async function saveWeek(apply=false){if(!data||busy)return;busy=true;weeklyMessage='';try{let url='/api/admin/booking-hours',body:unknown={weeklyHours:weeklyDraft};if(apply){const monday=dateAt(selectedDate);monday.setUTCDate(monday.getUTCDate()-(monday.getUTCDay()+6)%7);url='/api/admin/booking-calendar';body={weekStart:dateString(monday)};}const response=await fetch(url,{method:apply?'POST':'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw Error();if(!apply){data={...data,weeklyHours:structuredClone($state.snapshot(weeklyDraft))};weeklyDirty=false;}weeklyMessage=apply?'applied':'saved';void loadCalendar(true);}catch{weeklyMessage='error';}finally{busy=false;}}
 let slots=$derived(Array.from({length:24},(_,i)=>{const minutes=8*60+i*30;return `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;}));
 const dateAt=(value:string)=>new Date(`${value}T12:00:00Z`);
 const dateString=(d:Date)=>`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
 const weekday=(value:string)=>String(dateAt(value).getUTCDay());
 const monthLabel=(value:string)=>new Intl.DateTimeFormat(lang,{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${value}-01T12:00:00Z`));
 const dayLabel=(value:string)=>new Intl.DateTimeFormat(lang,{weekday:'long',month:'long',day:'numeric',year:'numeric',timeZone:'UTC'}).format(dateAt(value));
 const slotFormatter=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
 const slotParts=(value:string)=>{const parts=slotFormatter.formatToParts(new Date(value));const get=(name:string)=>parts.find(part=>part.type===name)?.value??'';return {date:`${get('year')}-${get('month')}-${get('day')}`,time:`${get('hour')}:${get('minute')}`};};
 let dayCells=$derived.by(()=>{if(!viewMonth)return [];const first=new Date(`${viewMonth}-01T12:00:00Z`),offset=(first.getUTCDay()+6)%7,days=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();return [...Array(offset).fill(''),...Array.from({length:days},(_,i)=>dateString(new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth(),i+1))))];});
 let currentHours=$derived.by(()=>{if(!data||!selectedDate)return {};if(drafts[selectedDate])return drafts[selectedDate];return data.overrides[selectedDate]??data.weeklyHours[weekday(selectedDate)]??{};});
 let hasOverride=$derived(!!(data&&Object.hasOwn(data.overrides,selectedDate)));
 let monthHasWindow=$derived.by(()=>{if(!data||!viewMonth)return false;return data.to.slice(0,7)>=viewMonth&&data.from.slice(0,7)<=viewMonth;});
 let monthBefore=$derived(!!data&&viewMonth>data.from.slice(0,7));
 let monthAfter=$derived(!!data&&viewMonth<data.to.slice(0,7));
 const dateInWindow=(value:string)=>!!data&&value>=data.from&&value<=data.to;
 let indexedSlots=$derived.by(()=>{const days=new Map<string,Map<string,CalendarSlot>>();for(const slot of data?.calendarSlots??[]){const part=slotParts(slot.startAt);if(!days.has(part.date))days.set(part.date,new Map());days.get(part.date)!.set(part.time,slot);}return days;});
 const daySlots=(value:string)=>[...(indexedSlots.get(value)?.values()??[])];
 const slotAt=(value:string,time:string)=>indexedSlots.get(value)?.get(time);
 const bookingAt=(slot?:CalendarSlot)=>slot?data?.bookings?.find(booking=>booking.startAt===slot.startAt):undefined;
 function daySummary(value:string){const current=daySlots(value);if(current.some(s=>s.status==='booked'))return t('booked');if(current.some(s=>s.status==='unavailable'))return data?.source==='unavailable'?t('sourceUnavailable'):t('busy');if(current.some(s=>s.status==='contact_directly'))return t('contact');if(current.some(s=>s.status==='available'))return t('open');return t('closed');}
 function statusText(status:string){return status==='available'?t('open'):status==='contact_directly'?t('contact'):status==='booked'?t('booked'):status==='unavailable'?data?.source==='unavailable'?t('sourceUnavailable'):t('busy'):t('closed');}
 function dateHasDirty(value:string){return !!dirtyDates[value];}
 async function loadCalendar(quiet=false){if(refreshing)return;refreshing=true;if(!quiet){loadError=false;setupRequired=false;}try{const response=await fetch('/api/admin/booking-calendar',{cache:'no-store'});const next=await response.json();if(!response.ok){if(next.error==='booking_calendar_setup_required')setupRequired=true;throw Error();}if(!Array.isArray(next.calendarSlots)||!next.weeklyHours||!next.overrides)throw Error();data=next as Payload;if(!weeklyDirty)weeklyDraft=structuredClone(next.weeklyHours);if(!selectedDate||selectedDate<data.from||selectedDate>data.to)selectedDate=data.from;if(!viewMonth)viewMonth=selectedDate.slice(0,7);if(viewMonth<data.from.slice(0,7))viewMonth=data.from.slice(0,7);if(viewMonth>data.to.slice(0,7))viewMonth=data.to.slice(0,7);loadError=false;if(!quiet)message='';}catch{if(!data)loadError=true;else if(quiet)message='refreshFailed';}finally{refreshing=false;}}
 onMount(()=>{void loadCalendar();const timer=setInterval(()=>void loadCalendar(true),60000);const onFocus=()=>void loadCalendar(true);const onVisibility=()=>{if(document.visibilityState==='visible')void loadCalendar(true);};window.addEventListener('focus',onFocus);document.addEventListener('visibilitychange',onVisibility);return()=>{clearInterval(timer);window.removeEventListener('focus',onFocus);document.removeEventListener('visibilitychange',onVisibility);};});
 function changeMonth(step:number){if(!data)return;const next=new Date(`${viewMonth}-01T12:00:00Z`);next.setUTCMonth(next.getUTCMonth()+step);const value=dateString(next).slice(0,7);if(value>=data.from.slice(0,7)&&value<=data.to.slice(0,7))viewMonth=value;}
 function selectDate(value:string){if(!value||!dateInWindow(value))return;selectedDate=value;message='';}
 function setSlot(time:string,status:'available'|'contact_directly'|null){if(!selectedDate||busy)return;const overlay=slotAt(selectedDate,time);if(overlay&&(overlay.status==='booked'||overlay.status==='unavailable'&&data?.source!=='unavailable'))return;const next={...currentHours};if(status)next[time]=status;else delete next[time];drafts={...drafts,[selectedDate]:next};dirtyDates={...dirtyDates,[selectedDate]:true};message='';}
 async function save(reset=false){if(!data||!selectedDate||busy)return;const date=selectedDate,hours=structuredClone($state.snapshot(currentHours));busy=true;message='';try{const response=await fetch('/api/admin/booking-calendar',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({date,hours:reset?null:hours})});const result=await response.json().catch(()=>({}));if(!response.ok)throw Error();const next={...data.overrides};if(reset)delete next[date];else next[date]=hours;data={...data,overrides:next};delete drafts[date];drafts={...drafts};delete dirtyDates[date];dirtyDates={...dirtyDates};message=reset?'resetDone':'saved';void loadCalendar(true);}catch{message=reset?'resetError':'saveError';}finally{busy=false;}}
</script>

<section class="booking-calendar" aria-labelledby="admin-booking-calendar-title">
 <header><div><h2 id="admin-booking-calendar-title">{t('title')}</h2><p>{t('lead')}</p></div>{#if data}<div class="source"><span>{data.source==='google-calendar'?t('sourceGoogle'):data.source==='unavailable'?t('sourceUnavailable'):t('sourceDb')}</span><span>{t('zone')}</span></div>{/if}</header>
 {#if data?.source==='unavailable'}<div class="notice" role="alert">{t('syncFailed')}</div>{/if}
 {#if loadError}<div class="notice" role="alert">{setupRequired?t('setupRequired'):t('loadError')} <button class="text-link" onclick={()=>loadCalendar()}>{t('retry')}</button></div>
 {:else if data}
 <section class="weekly-default" aria-labelledby="weekly-default-title">
  <h3 id="weekly-default-title">{w('title')}</h3><p>{w('description')}</p>
  <div class="weekly-table"><table><thead><tr><th>{w('day')}</th><th>{w('open')}</th><th>{w('from')}</th><th>{w('to')}</th></tr></thead><tbody>
   {#each weekDays as day}{@const range=hoursRange(day)}{@const enabled=Object.keys(weeklyDraft[String(day)]??{}).length>0}<tr><th>{weekDayLabel(day)}</th><td><input type="checkbox" aria-label={`${weekDayLabel(day)} ${w('open')}`} checked={enabled} disabled={busy} onchange={event=>changeWeekDay(day,event.currentTarget.checked)} /></td><td><select aria-label={`${weekDayLabel(day)} ${w('from')}`} disabled={busy||!enabled} value={range.start} onchange={event=>changeWeekDay(day,true,event.currentTarget.value,range.end)}>{#each slots as time}<option value={time}>{time}</option>{/each}</select></td><td><select aria-label={`${weekDayLabel(day)} ${w('to')}`} disabled={busy||!enabled} value={range.end} onchange={event=>changeWeekDay(day,true,range.start,event.currentTarget.value)}>{#each [...slots.slice(1),'20:00'] as time}<option value={time}>{time}</option>{/each}</select></td></tr>{/each}
  </tbody></table></div>
  <div class="actions"><button class="save" disabled={busy||!weeklyDirty} onclick={()=>saveWeek()}>{w('save')}</button><button class="reset" disabled={busy} onclick={restoreWeek}>{w('restore')}</button><button class="reset" disabled={busy||weeklyDirty} onclick={()=>saveWeek(true)}>{w('apply')}</button></div>
  {#if weeklyDirty}<p class="hint">{w('unsaved')}</p>{/if}{#if weeklyMessage}<p role="status" class="feedback" class:error={weeklyMessage==='error'||weeklyMessage==='rangeError'}>{w(weeklyMessage as keyof typeof weeklyWords.en)}</p>{/if}
 </section>
 <div class="layout">
  <div class="calendar-pane"><div class="month-bar"><button class="nav-button" disabled={!monthBefore||refreshing} aria-label={t('prev')} onclick={()=>changeMonth(-1)}>‹</button><h3>{monthLabel(viewMonth)}</h3><button class="nav-button" disabled={!monthAfter||refreshing} aria-label={t('next')} onclick={()=>changeMonth(1)}>›</button></div>
   <div class="weekdays">{#each (lang==='th'?['จ','อ','พ','พฤ','ศ','ส','อา']:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']) as day}<span>{day}</span>{/each}</div>
   <div class="days">{#each dayCells as date,i (i)}{#if date}<button class="day" class:selected={selectedDate===date} class:outside={!dateInWindow(date)} class:dirty={dateHasDirty(date)} disabled={!dateInWindow(date)} aria-pressed={selectedDate===date} aria-label={`${dayLabel(date)}: ${dateInWindow(date)?daySummary(date):t('noWindow')}`} onclick={()=>selectDate(date)}><span>{Number(date.slice(-2))}</span>{#if dateInWindow(date)}<small>{daySummary(date)}</small>{#if dateHasDirty(date)}<i aria-label={t('unsaved')}></i>{/if}{/if}</button>{:else}<span aria-hidden="true"></span>{/if}{/each}</div>
   <p class="window">{t('window')}: {data.from} – {data.to}</p>
  </div>
  <div class="detail"><div class="detail-head"><div><span class="eyebrow">{t('date')}</span><h3>{dayLabel(selectedDate)}</h3></div><span class="mode">{hasOverride||dirtyDates[selectedDate]?t('override'):t('default')}</span></div>
   {#if dateHasDirty(selectedDate)}<p class="unsaved" role="status">{t('unsaved')}</p>{/if}
   <div class="slot-grid"><div class="slot-title"><strong>{t('slots')}</strong><span>{t('status')}</span></div>
    {#each slots as time (time)}{@const current=currentHours[time]??'closed'}{@const overlay=slotAt(selectedDate,time)}{@const booking=bookingAt(overlay)}{@const locked=overlay?.status==='booked'||overlay?.status==='unavailable'&&data?.source!=='unavailable'}<div class="slot-row" class:locked><div class="time">{time}</div>{#if locked&&booking}<div class="booking-summary"><strong>{booking.contactName}</strong><span>{booking.contactInformation} · {booking.instrument}</span><details><summary>{lang==='th'?'ดูรายละเอียด':'View details'}</summary><dl><dt>{lang==='th'?'แผนซ่อม':'Repair plan'}</dt><dd>{booking.service}</dd><dt>{lang==='th'?'หมายเหตุ':'Notes'}</dt><dd>{booking.notes||'—'}</dd><dt>{lang==='th'?'เวลาและสถานะ':'Time and status'}</dt><dd>{booking.startAt} – {booking.endAt} · {booking.status}</dd></dl></details></div>{:else if locked}<span class="overlay" class:booked={overlay?.status==='booked'}>{statusText(overlay?.status??'unavailable')}</span>{:else}<div class="choices">{#if overlay}<span class="overlay">{statusText(overlay.status)}</span>{/if}<button class="choice available" class:active={current==='available'} disabled={busy} aria-pressed={current==='available'} onclick={()=>setSlot(time,current==='available'?null:'available')}>{t('open')}</button><button class="choice contact" class:active={current==='contact_directly'} disabled={busy} aria-pressed={current==='contact_directly'} onclick={()=>setSlot(time,current==='contact_directly'?null:'contact_directly')}>{t('contact')}</button><button class="choice close" class:active={current==='closed'} disabled={busy} aria-pressed={current==='closed'} onclick={()=>setSlot(time,null)}>{t('closed')}</button></div>{/if}</div>{/each}
   </div>
   <p class="hint">{t('note')}</p><p class="legend"><span class="dot available-dot"></span>{t('open')} <span class="dot contact-dot"></span>{t('contact')} <span class="dot busy-dot"></span>{t('busy')} <span class="dot booked-dot"></span>{t('booked')}</p>
   <div class="actions"><button class="save" disabled={busy||!dateHasDirty(selectedDate)} onclick={()=>save()}>{busy?t('saving'):t('save')}</button><button class="reset" disabled={busy||!hasOverride&&!dateHasDirty(selectedDate)} onclick={()=>save(true)}>{t('reset')}</button><button class="refresh" disabled={refreshing} onclick={()=>loadCalendar(true)}>{refreshing?t('refreshing'):t('refresh')}</button></div>
   {#if message}<p class="feedback" class:error={message==='saveError'||message==='resetError'||message==='refreshFailed'} role="status">{message==='saved'?t('saved'):message==='resetDone'?t('resetDone'):message==='saveError'?t('saveError'):message==='resetError'?t('resetError'):t('refreshFailed')}</p>{/if}
  </div>
 </div>{/if}
</section>

<style>
